      "rawTitle": "牛登碑（元康八年）",
      "title": "牛登碑",
      "name": "牛登碑",
      "type": "碑刻",
      "materialType": "碑刻",
      "sourceTitle": "《两晋金石录（2025.06.21更新）》",
      "sourceDocument": "两晋金石录（2025.06.21更新）.docx",
      "polity": "晋",
      "period": "西晋",
      "archiveKind": "核心",
